import json, glob, sys
sys.path.insert(0,'.')
from phase_b_grade import grade_record
from analyze import wilcoxon

def load(d):
    out={}
    for p in glob.glob(d+'/*.json'):
        r=grade_record(json.loads(open(p).read()))
        out[(r['id'],r['arm'])]=r
    return out

eb_main={t['id'] for t in json.loads(open('tasks-v3.json').read()) if t['branch']=='main'}
mv_main={t['id'] for t in json.loads(open('tasks-marvin.json').read()) if t['branch']=='main'}
tiny={t['id'] for t in json.loads(open('tasks-v3.json').read()) if t['branch']!='main'} | \
     {t['id'] for t in json.loads(open('tasks-marvin.json').read()) if t['branch']!='main'}

cells = {'sonnet/base': load('runs-b'), 'haiku/base': load('runs-b-haiku'),
         'fable/base': load('runs-b-fable'), 'sonnet/XL(1209)': load('runs-b-xl')}

def pair(cell, a, b, metric='recall', ids=None):
    data=cells[cell]
    tids={i for (i,arm) in data if arm==a} & {i for (i,arm) in data if arm==b}
    if ids: tids &= ids
    d=[data[(i,b)][metric]-data[(i,a)][metric] for i in tids]
    if not d: return
    p=wilcoxon(d)
    ma=sum(data[(i,a)][metric] for i in tids)/len(tids); mb=sum(data[(i,b)][metric] for i in tids)/len(tids)
    sig = '**' if p==p and p<0.05 else '  '
    print(f"{cell:16s} {b:5s}-{a:5s} {metric:7s} n={len(d):3d} {ma:.3f}->{mb:.3f} d={sum(d)/len(d):+.3f} p={p:.4f}{sig}" if p==p else f"{cell} {b}-{a} {metric} n={len(d)} nan")

for cell in cells:
    for metric in ('recall','tokens'):
        pair(cell,'brain','rank',metric)
        pair(cell,'grep','rank',metric)
        pair(cell,'brain','grep',metric)
    print()
print('--- corpus-size strata (recall, rank-vs-brain) ---')
for cell in ('sonnet/base','haiku/base'):
    for label, ids in (('tiny<25',tiny),('mv-main~300',mv_main),('eb-main~876',eb_main)):
        pair(cell,'brain','rank','recall',ids)
EOF

