              "handle": "evisdren",
              "is_primary": true
            }
          ]
        }
      }
    ],
    "reviewers": [],
    "ready_for_review": true,
    "has_code_changes": true,
    "comment_count": 2,
    "unresolved_count": 3,
    "created_at": "2026-10-13T23:58:17.264Z",
    "updated_at": "2026-10-15T03:18:44.967Z",
    "merged_at": null,
    "last_activity_at": "2026-10-15T03:18:44.136Z",
    "phase": "reviewing",
    "checkpoint_count": 2,
    "body_document": {
      "id": "01M4VV7QP2GKEBMN7CNC1ZDFKD",
      "document_key": "trail:01M4VV7QNGGNQC8YNQWVB6TE9Y:body",
      "schema_version": 1,
      "content_json": {
        "type": "doc",
        "content": [
          {
            "type": "heading",
            "attrs": {
              "level": 1
            },
            "content": [
              {
                "text": "Proposal",
                "type": "text"
              }
            ]
          },
          {
            "type": "paragraph",
            "content": [
              {
                "text": "Replace the facts-path semantic machinery — the bundled 31 MB Model2Vec embedder (",
                "type": "text"
              },
              {
                "text": "assets/embedmodel.bin",
                "type": "text",
                "marks": [
                  {
                    "type": "code",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": "), per-branch vector caches, RRF fusion, and the sqlite-vec cgo variant — with a ~200-line in-process BM25 ranker plus taxonomy/kind/date filters, slotted in at the existing ",
                "type": "text"
              },
              {
                "text": "rankFactsFused(rr=nil)",
                "type": "text",
                "marks": [
                  {
                    "type": "code",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " seam. Semantic becomes opt-in or is deleted.",
                "type": "text"
              }
            ]
          },
          {
            "type": "paragraph",
            "content": [
              {
                "text": "Net: ≈ −3,000 lines (+~1,260 test lines), −31 MB per binary (~47% raw, ~59% of the compressed download), −1 build variant, −~300 MB peak RSS per query.",
                "type": "text"
              }
            ]
          },
          {
            "type": "heading",
            "attrs": {
              "level": 1
            },
            "content": [
              {
                "text": "Evidence",
                "type": "text"
              }
            ]
          },
          {
            "type": "paragraph",
            "content": [
              {
                "text": "1,748 live Claude Code agent runs (~$365) across two repos (entire-brain, marvin), three models, corpus sizes 5→1,209 facts. Each task is a real captured session's opening request; gold labels are that session's distilled facts, judge-refined and fixed before any arm ran. One agent per (task, arm, model), identical prompt and budget — only the search tool differed. Paired Wilcoxon per cell; deterministic grading (fact IDs in the final answer vs gold).",
                "type": "text"
              }
            ]
          },
          {
            "type": "paragraph",
            "content": [
              {
                "text": "Arms: ",
                "type": "text"
              },
              {
                "text": "brain query",
                "type": "text",
                "marks": [
                  {
                    "type": "code",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " (shipped hybrid = lexical + embeddings + RRF) · naive term-match CLI · grep (Read/Grep/Glob over ",
                "type": "text"
              },
              {
                "text": "facts files",
                "type": "text",
                "marks": [
                  {
                    "type": "code",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " export) · ",
                "type": "text"
              },
              {
                "text": "rank2 = BM25 + ",
                "type": "text",
                "marks": [
                  {
                    "type": "bold",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": "--path/--kind/--since",
                "type": "text",
                "marks": [
                  {
                    "type": "code",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " filters + ",
                "type": "text",
                "marks": [
                  {
                    "type": "bold",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": "--list-paths",
                "type": "text",
                "marks": [
                  {
                    "type": "code",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " (the proposed replacement, tested as a Python prototype; the Go port is the same deterministic algorithm).",
                "type": "text"
              }
            ]
          },
          {
            "type": "heading",
            "attrs": {
              "level": 2
            },
            "content": [
              {
                "text": "Agent recall and token cost, semantic → rank2",
                "type": "text"
              }
            ]
          },
          {
            "type": "paragraph",
            "content": [
              {
                "text": "| Model | Facts | Tasks | Recall | Tokens/task | Verdict | |---|---|---|---|---|---| | sonnet | up to 878 | 149 | 0.629 → ",
                "type": "text"
              },
              {
                "text": "0.692",
                "type": "text",
                "marks": [
                  {
                    "type": "bold",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " | 218k → 157k (−28%) | rank2 better (p=0.022; precision too, p=0.006) | | haiku 4.5 | up to 878 | 149 | ",
                "type": "text"
              },
              {
                "text": "0.618",
                "type": "text",
                "marks": [
                  {
                    "type": "bold",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " → 0.563 | 307k → 251k (−18%) | semantic marginal (p=0.051, precision tied) | | fable 5 | up to 878 | 60 | 0.513 → ",
                "type": "text"
              },
              {
                "text": "0.595",
                "type": "text",
                "marks": [
                  {
                    "type": "bold",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " | 194k → 180k | rank2 ahead (p=0.07) | | sonnet | 1,209 | 79 | 0.317 → ",
                "type": "text"
              },
              {
                "text": "0.326",
                "type": "text",
                "marks": [
                  {
                    "type": "bold",
                    "attrs": {}
                  }
                ]
              },
              {
                "text": " | 256k → 203k (−20%) | tie (p=0.88) |",
                "type": "text"
              }
            ]
          },
          {
            "type": "paragraph",
            "content": [
              {
                "text": "Naive grep is NOT the proposal — it collapses on weak models (0.215) and at scale (0.154). The ranked top-k interface is load-bearing; BM25 + filters supplies it without the model.",
                "type": "text"
              }
            ]
          },
          {
            "type": "heading",
            "attrs": {
              "level": 2
            },
            "content": [
              {
                "text": "Resources (measured, 1,209-fact corpus)",
                "type": "text"
              }
            ]
          },
          {
            "type": "paragraph",
            "content": [
              {
                "text": "| | semantic hybrid | rank2 prototype | |---|---|---| | peak RSS/query | 316 MB (embedder ≈ 111 MB of it) | 14 MB | | latency/query | 0.60 s | 0.12 s | | disk | 19 MB store + 2.4 MB vectors + 31 MB model/binary | 4.8 MB flat files (Go port reads the store in-process) |",
                "type": "text"
              }
            ]
          },
          {
            "type": "heading",
            "attrs": {
              "level": 2
            },
            "content": [
              {
                "text": "Why semantic loses its rationale",
                "type": "text"
              }
            ]
          },
          {
            "type": "bulletList",
            "content": [
              {
                "type": "listItem",
                "content": [
                  {
                    "type": "paragraph",
                    "content": [
                      {
                        "text": "Static ranking: semantic beats Brain's own lexical arm (+0.36 useful/1k, p\u003c0.0001, consistent with the 2026-06-09 ledger row) — but naive grep ALSO beats Brain's lexical arm (p=0.0003), and BM25 beats semantic single-shot at scale (recall@10 0.202 vs 0.170).",
                        "type": "text"
                      }
                    ]
                  }
                ]
              },
              {
                "type": "listItem",
                "content": [
