108		// leaf that fails these is corrupt and must classify as such in health
109		// output, not report as a healthy pending/current state.
110		if progress.SchemaVersion != memoryVectorSchema || progress.ModelID == "" || progress.UpdatedAt.IsZero() ||
111			progress.HistoryAdded < 0 || progress.ConversationAdded < 0 ||
