1	package cli
2	
3	import (
4		"math"
5		"strings"
6		"time"
7	)
8	
9	// BM25 replaces the flat term-overlap text score on the facts path. The flat
10	// scorer collapses at corpus scale: common terms match hundreds of facts and
11	// the discriminative rare term no longer decides the ordering. BM25's IDF
12	// weighting fixes exactly that, and the 2026-10 retrieval eval (eval ledger;
13	// trail #278) measured it matching or beating the semantic fusion arm across
14	// models and corpus sizes, which is why the embedder was removed.
15	const (
16		bm25K1 = 1.2
17		bm25B  = 0.75
18	
19		// Boost scales re-expressed for the BM25 range (one strong rare-term hit
20		// contributes roughly idf ~= 4-7). The old int scorer weighted a locus
21		// token at 6x a term hit and closed-negative at 3x; these keep those
22		// proportions.
23		bm25LocusBoost          = 8.0
24		bm25ClosedNegativeBoost = 4.0
25	)
26	
27	// factSearchTokens are the indexable tokens of one fact: its text plus its
28	// taxonomy paths (dots split so "architecture.sync.auth" matches "sync").
29	// Facts index BOTH plain lowercase tokens ("mysql") and the camel-split form
30	// the history normalizer produces ("my sql"), so a query matches whichever
31	// shape the asker types. The plain form is what the shipped-decision eval
32	// measured (trail #278); the camel-split additions only widen reachability.
33	func factSearchTokens(f factRecord) []string {
34		haystack := f.Text + " " + strings.ReplaceAll(strings.Join(f.Paths, " "), ".", " ")
35		tokens := factPlainTokens(haystack)
36		seen := make(map[string]struct{}, len(tokens)*2)
37		for _, t := range tokens {
38			seen[t] = struct{}{}
39		}
40		for _, t := range strings.Fields(normalizeHistorySearchText(haystack)) {
41			if _, ok := seen[t]; ok {
42				continue
43			}
44			seen[t] = struct{}{}
45			tokens = append(tokens, t)
46		}
47		return tokens
48	}
49	
50	// factPlainTokens lowercases and splits on non-alphanumerics (underscore
51	// kept), the tokenization the retrieval eval measured.
52	func factPlainTokens(text string) []string {
53		lower := strings.ToLower(text)
54		return strings.FieldsFunc(lower, func(r rune) bool {
55			return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '_')
56		})
57	}
58	
59	// factQueryTerms are the deduplicated plain tokens of a query, with the
60	// history stopword list applied so "how does the" carries no weight.
61	func factQueryTerms(query string) []string {
62		seen := map[string]struct{}{}
63		var terms []string
64		for _, t := range factPlainTokens(query) {
65			if len(t) < 2 || historyQueryStopword(t) {
66				continue
67			}
68			if _, ok := seen[t]; ok {
69				continue
70			}
71			seen[t] = struct{}{}
72			terms = append(terms, t)
73		}
74		return terms
75	}
76	
77	// bm25Corpus holds the per-call corpus statistics BM25 needs. Recomputed per
78	// query over the candidate set — ponytail: O(corpus) per query, measured at
79	// well under a millisecond for 1,209 facts; an inverted index is the upgrade
80	// path if fact counts grow by orders of magnitude.
81	type bm25Corpus struct {
82		docTokens [][]string
83		df        map[string]int
84		avgLen    float64
85	}
86	
87	func newBM25Corpus(facts []factRecord) bm25Corpus {
88		c := bm25Corpus{
89			docTokens: make([][]string, len(facts)),
90			df:        make(map[string]int, len(facts)*8),
91		}
92		total := 0
93		for i, f := range facts {
94			tokens := factSearchTokens(f)
95			c.docTokens[i] = tokens
96			total += len(tokens)
97			seen := make(map[string]struct{}, len(tokens))
98			for _, t := range tokens {
99				if _, ok := seen[t]; ok {
100					continue
101				}
102				seen[t] = struct{}{}
103				c.df[t]++
104			}
105		}
106		if len(facts) > 0 {
107			c.avgLen = float64(total) / float64(len(facts))
108		}
109		return c
110	}
111	
112	// bm25Score is the Okapi BM25 text relevance of candidate i for the query
113	// terms, over this corpus.
114	func (c bm25Corpus) bm25Score(i int, terms []string) float64 {
115		tokens := c.docTokens[i]
116		if len(tokens) == 0 || len(terms) == 0 {
117			return 0
118		}
119		tf := make(map[string]int, len(tokens))
120		for _, t := range tokens {
121			tf[t]++
122		}
123		n := float64(len(c.docTokens))
124		score := 0.0
125		for _, term := range terms {
126			f := float64(tf[term])
127			if f == 0 {
128				continue
129			}
130			idf := math.Log((n-float64(c.df[term])+0.5)/(float64(c.df[term])+0.5) + 1)
131			norm := 1 - bm25B + bm25B*float64(len(tokens))/c.avgLen
132			score += idf * f * (bm25K1 + 1) / (f + bm25K1*norm)
133		}
134		return score
135	}
136	
137	// factBM25Score is the full facts ranking score: BM25 text relevance plus the
138	// two previously measured boosts (shared code locus, closed-negative kind).
139	// Boosts apply only to facts that already match, so neither creates a match on
140	// its own — same contract as the scorer this replaces.
141	func factBM25Score(f factRecord, c bm25Corpus, i int, terms []string, queryLocus []string) float64 {
142		score := c.bm25Score(i, terms)
143		if score <= 0 {
144			return 0
145		}
146		if overlap := locusOverlapTokens(queryLocus, factLocusOf(f)); overlap > 0 {
147			score += float64(overlap) * bm25LocusBoost
148		}
149		if factKindOrInferred(f) == factKindClosedNegative {
150			score += bm25ClosedNegativeBoost
151		}
152		return score
153	}
154	
155	// filterFacts narrows candidates by taxonomy path prefix, fact kind, and
156	// minimum update time. Zero values skip that filter. A path prefix matches a
157	// whole segment boundary: "architecture.sync" matches "architecture.sync" and
158	// "architecture.sync.auth", not "architecture.syncextra".
159	func filterFacts(facts []factRecord, pathPrefix, kind string, since time.Time) []factRecord {
160		if pathPrefix == "" && kind == "" && since.IsZero() {
161			return facts
162		}
163		out := make([]factRecord, 0, len(facts))
164		for _, f := range facts {
165			if kind != "" && f.Kind != kind {
166				continue
167			}
168			if !since.IsZero() && f.UpdatedAt.Before(since) {
169				continue
170			}
171			if pathPrefix != "" && !factMatchesPathPrefix(f, pathPrefix) {
172				continue
173			}
174			out = append(out, f)
175		}
176		return out
177	}
178	
179	func factMatchesPathPrefix(f factRecord, prefix string) bool {
180		for _, p := range f.Paths {
181			if p == prefix || strings.HasPrefix(p, prefix+".") {
182				return true
183			}
184		}
185		return false
186	}

