package cli

import (
	"testing"
	"time"
)

func bm25Fact(id, text string, paths ...string) factRecord {
	if len(paths) == 0 {
		paths = []string{"architecture.test"}
	}
	return factRecord{
		ID: id, Text: text, Paths: paths,
		Status: factStatusActive, UpdatedAt: time.Now(),
	}
}

// A document holding the query's rare term must outrank one matching only the
// common term, even when the common-term document repeats it. This is the
// measured failure of the flat scorer at corpus scale (term collisions), and
// the reason BM25 replaces it.
func TestBM25RareTermOutranksCommon(t *testing.T) {
	facts := []factRecord{
		bm25Fact("fact:common1", "the sync loop retries sync requests with sync batching"),
		bm25Fact("fact:common2", "sync clients refresh tokens before sync windows"),
		bm25Fact("fact:common3", "sync state is cached between sync runs"),
		bm25Fact("fact:rare", "sync retries use exponential backoff with jitter"),
	}
	got := rankFacts(facts, "sync backoff", 2, false)
	if len(got) == 0 || got[0].ID != "fact:rare" {
		t.Fatalf("expected fact:rare first, got %+v", factIDs(got))
	}
}

// Term repetition saturates: a fact matching two distinct query terms beats a
// fact stuffing one term many times.
func TestBM25SaturationPrefersDistinctTerms(t *testing.T) {
	facts := []factRecord{
		bm25Fact("fact:stuffed", "distill distill distill distill distill distill distill distill"),
		bm25Fact("fact:both", "the distill pipeline writes a manifest after each run"),
	}
	got := rankFacts(facts, "distill manifest", 2, false)
	if len(got) == 0 || got[0].ID != "fact:both" {
		t.Fatalf("expected fact:both first, got %+v", factIDs(got))
	}
}

// With equal term evidence, the shorter fact ranks first (length
// normalization), and recency still breaks exact ties.
func TestBM25LengthNormalization(t *testing.T) {
	long := "the embedder loads lazily on first query and caches vectors per branch " +
		"while unrelated sentences about many other subsystems pad this fact out " +
		"with words that do not touch the query at all in any way whatsoever"
	facts := []factRecord{
		bm25Fact("fact:long", long),
		bm25Fact("fact:short", "the embedder caches vectors per branch"),
	}
	got := rankFacts(facts, "embedder vectors", 2, false)
	if len(got) == 0 || got[0].ID != "fact:short" {
		t.Fatalf("expected fact:short first, got %+v", factIDs(got))
	}
}

// The locus boost survives the BM25 rewrite: a shared code identifier still
// lifts a fact above a plain-text match of similar strength.
func TestBM25KeepsLocusBoost(t *testing.T) {
	withLocus := bm25Fact("fact:locus", "retrieval reads the fact store at query time")
	withLocus.Locus = []string{"facts_query.go"}
	facts := []factRecord{
		bm25Fact("fact:plain", "retrieval reads the fact store during query handling"),
		withLocus,
	}
	got := rankFacts(facts, "retrieval in facts_query.go", 2, false)
	if len(got) == 0 || got[0].ID != "fact:locus" {
		t.Fatalf("expected fact:locus first, got %+v", factIDs(got))
	}
}

// Empty queries keep the recency-listing contract.
func TestBM25EmptyQueryListsByRecency(t *testing.T) {
	older := bm25Fact("fact:older", "anything")
	older.UpdatedAt = time.Now().Add(-time.Hour)
	newer := bm25Fact("fact:newer", "anything")
	got := rankFacts([]factRecord{older, newer}, "", 2, false)
	if len(got) != 2 || got[0].ID != "fact:newer" {
		t.Fatalf("expected recency listing, got %+v", factIDs(got))
	}
}

func TestFilterFacts(t *testing.T) {
	a := bm25Fact("fact:a", "x", "architecture.sync.auth")
	a.Kind = factKindDecision
	a.UpdatedAt = time.Date(2026, 9, 1, 0, 0, 0, 0, time.UTC)
	b := bm25Fact("fact:b", "x", "project.hosted")
	b.Kind = factKindGotcha
	b.UpdatedAt = time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)
	facts := []factRecord{a, b}

	if got := filterFacts(facts, "architecture.sync", "", time.Time{}); len(got) != 1 || got[0].ID != "fact:a" {
		t.Fatalf("path filter: got %+v", factIDs(got))
	}
	if got := filterFacts(facts, "", factKindGotcha, time.Time{}); len(got) != 1 || got[0].ID != "fact:b" {
		t.Fatalf("kind filter: got %+v", factIDs(got))
	}
	since := time.Date(2026, 9, 15, 0, 0, 0, 0, time.UTC)
	if got := filterFacts(facts, "", "", since); len(got) != 1 || got[0].ID != "fact:b" {
		t.Fatalf("since filter: got %+v", factIDs(got))
	}
	if got := filterFacts(facts, "", "", time.Time{}); len(got) != 2 {
		t.Fatalf("no filter: got %+v", factIDs(got))
	}
}

func factIDs(facts []factRecord) []string {
	ids := make([]string, len(facts))
	for i, f := range facts {
		ids[i] = f.ID
	}
	return ids
}

// Non-ASCII queries must produce terms: the ASCII-only plain tokenizer alone
// yields nothing for CJK/Cyrillic and truncates accents (trail #278 review
// finding). The query side unions the Unicode-aware normalizer's tokens,
// mirroring what factSearchTokens does for documents.
func TestBM25UnicodeQueriesMatch(t *testing.T) {
	facts := []factRecord{
		bm25Fact("fact:cafe", "the café menu service caches prices"),
		bm25Fact("fact:cyrillic", "сервис кеширует цены меню"),
		bm25Fact("fact:cjk", "服务缓存菜单价格"),
		bm25Fact("fact:other", "unrelated retry backoff fact"),
	}
	for query, want := range map[string]string{
		"café menu":   "fact:cafe",
		"сервис цены": "fact:cyrillic",
		"菜单价格":        "fact:cjk",
	} {
		got := rankFacts(facts, query, 1, false)
		if len(got) == 0 || got[0].ID != want {
			t.Errorf("query %q: got %v, want %s", query, factIDs(got), want)
		}
	}
}

package cli

import (
	"math"
	"strings"
	"time"
	"unicode"
)

// BM25 replaces the flat term-overlap text score on the facts path. The flat
// scorer collapses at corpus scale: common terms match hundreds of facts and
// the discriminative rare term no longer decides the ordering. BM25's IDF
// weighting fixes exactly that, and the 2026-10 retrieval eval (eval ledger;
// trail #278) measured it matching or beating the semantic fusion arm across
// models and corpus sizes, which is why the embedder was removed.
const (
	bm25K1 = 1.2
	bm25B  = 0.75

	// Boost scales re-expressed for the BM25 range (one strong rare-term hit
	// contributes roughly idf ~= 4-7). The old int scorer weighted a locus
	// token at 6x a term hit and closed-negative at 3x; these keep those
	// proportions.
	bm25LocusBoost          = 8.0
	bm25ClosedNegativeBoost = 4.0
)

// factSearchTokens are the indexable tokens of one fact: its text plus its
// taxonomy paths (dots split so "architecture.sync.auth" matches "sync").
// Facts index BOTH plain lowercase tokens ("mysql") and the camel-split form
// the history normalizer produces ("my sql"), so a query matches whichever
// shape the asker types. The plain form is what the shipped-decision eval
// measured (trail #278); the camel-split additions only widen reachability.
func factSearchTokens(f factRecord) []string {
	haystack := f.Text + " " + strings.ReplaceAll(strings.Join(f.Paths, " "), ".", " ")
	tokens := factPlainTokens(haystack)
	seen := make(map[string]struct{}, len(tokens)*2)
	for _, t := range tokens {
		seen[t] = struct{}{}
	}
	for _, t := range strings.Fields(normalizeHistorySearchText(haystack)) {
		for _, piece := range expandCJKBigrams(t) {
			if _, ok := seen[piece]; ok {
				continue
			}
			seen[piece] = struct{}{}
			tokens = append(tokens, piece)
		}
	}
	return tokens
}

// expandCJKBigrams splits a normalized token into word pieces for scripts
// written without spaces: runs of Han/Kana/Hangul become character bigrams
// (the standard CJK analyzer trick), everything else passes through whole.
// Without this a CJK query tokenizes to one long run that never equals the
// fact's equally long run, and matching silently returns nothing — the old
// substring scorer handled CJK for free, so BM25 must too.
func expandCJKBigrams(token string) []string {
	runes := []rune(token)
	var out []string
	var plain []rune
	flushPlain := func() {
		if len(plain) > 0 {
			out = append(out, string(plain))
			plain = plain[:0]
		}
	}
	for i := 0; i < len(runes); {
		if !isCJKRune(runes[i]) {
			plain = append(plain, runes[i])
			i++
			continue
		}
		flushPlain()
		j := i
		for j < len(runes) && isCJKRune(runes[j]) {
			j++
		}
		if j-i == 1 {
			out = append(out, string(runes[i:j]))
		}
		for k := i; k+1 < j; k++ {
			out = append(out, string(runes[k:k+2]))
		}
		i = j
	}
	flushPlain()
	return out
}

func isCJKRune(r rune) bool {
	return unicode.In(r, unicode.Han, unicode.Hiragana, unicode.Katakana, unicode.Hangul)
}

// factPlainTokens lowercases and splits on non-alphanumerics (underscore
// kept), the tokenization the retrieval eval measured.
func factPlainTokens(text string) []string {
	lower := strings.ToLower(text)
	return strings.FieldsFunc(lower, func(r rune) bool {
		return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '_')
	})
}

// factQueryTerms are the deduplicated query tokens, with the history stopword
// list applied so "how does the" carries no weight. Like factSearchTokens on
// the document side, the query unions the ASCII plain tokens with the
// Unicode-aware normalizer's tokens: the plain tokenizer alone yields nothing
// for CJK/Cyrillic queries and truncates accented words at the accent.
func factQueryTerms(query string) []string {
	seen := map[string]struct{}{}
	var terms []string
	add := func(t string) {
		if len(t) < 2 || historyQueryStopword(t) {
			return
		}
		if _, ok := seen[t]; ok {
			return
		}
		seen[t] = struct{}{}
		terms = append(terms, t)
	}
	for _, t := range factPlainTokens(query) {
		add(t)
	}
	for _, t := range strings.Fields(normalizeHistorySearchText(query)) {
		for _, piece := range expandCJKBigrams(t) {
			add(piece)
		}
	}
	return terms
}

// bm25Corpus holds the per-call corpus statistics BM25 needs. Recomputed per
// query over the candidate set — ponytail: O(corpus) per query, measured at
// well under a millisecond for 1,209 facts; an inverted index is the upgrade
// path if fact counts grow by orders of magnitude.
type bm25Corpus struct {
	docTokens [][]string
	df        map[string]int
	avgLen    float64
}

func newBM25Corpus(facts []factRecord) bm25Corpus {
	c := bm25Corpus{
		docTokens: make([][]string, len(facts)),
		df:        make(map[string]int, len(facts)*8),
	}
	total := 0
	for i, f := range facts {
		tokens := factSearchTokens(f)
		c.docTokens[i] = tokens
		total += len(tokens)
		seen := make(map[string]struct{}, len(tokens))
		for _, t := range tokens {
			if _, ok := seen[t]; ok {
				continue
			}
			seen[t] = struct{}{}
			c.df[t]++
		}
	}
	if len(facts) > 0 {
		c.avgLen = float64(total) / float64(len(facts))
	}
	return c
}

// bm25Score is the Okapi BM25 text relevance of candidate i for the query
// terms, over this corpus.
func (c bm25Corpus) bm25Score(i int, terms []string) float64 {
	tokens := c.docTokens[i]
	if len(tokens) == 0 || len(terms) == 0 {
		return 0
	}
	tf := make(map[string]int, len(tokens))
	for _, t := range tokens {
		tf[t]++
	}
	n := float64(len(c.docTokens))
	score := 0.0
	for _, term := range terms {
		f := float64(tf[term])
		if f == 0 {
			continue
		}
		idf := math.Log((n-float64(c.df[term])+0.5)/(float64(c.df[term])+0.5) + 1)
		norm := 1 - bm25B + bm25B*float64(len(tokens))/c.avgLen
		score += idf * f * (bm25K1 + 1) / (f + bm25K1*norm)
	}
	return score
}

// factBM25Score is the full facts ranking score: BM25 text relevance plus the
// two previously measured boosts (shared code locus, closed-negative kind).
// Boosts apply only to facts that already match, so neither creates a match on
// its own — same contract as the scorer this replaces.
func factBM25Score(f factRecord, c bm25Corpus, i int, terms []string, queryLocus []string) float64 {
	score := c.bm25Score(i, terms)
	if score <= 0 {
		return 0
	}
	if overlap := locusOverlapTokens(queryLocus, factLocusOf(f)); overlap > 0 {
		score += float64(overlap) * bm25LocusBoost
	}
	if factKindOrInferred(f) == factKindClosedNegative {
		score += bm25ClosedNegativeBoost
	}
	return score
}

// filterFacts narrows candidates by taxonomy path prefix, fact kind, and
// minimum update time. Zero values skip that filter. A path prefix matches a
// whole segment boundary: "architecture.sync" matches "architecture.sync" and
// "architecture.sync.auth", not "architecture.syncextra".
func filterFacts(facts []factRecord, pathPrefix, kind string, since time.Time) []factRecord {
	if pathPrefix == "" && kind == "" && since.IsZero() {
		return facts
	}
	out := make([]factRecord, 0, len(facts))
	for _, f := range facts {
		if kind != "" && f.Kind != kind {
			continue
		}
		if !since.IsZero() && f.UpdatedAt.Before(since) {
			continue
		}
		if pathPrefix != "" && !factMatchesPathPrefix(f, pathPrefix) {
			continue
		}
		out = append(out, f)
	}
	return out
}

func factMatchesPathPrefix(f factRecord, prefix string) bool {
	for _, p := range f.Paths {
		if p == prefix || strings.HasPrefix(p, prefix+".") {
			return true
		}
	}
	return false
}

tools.description:
Use this tool when you need to ask the user questions during execution. This allows you to: 1. Gather user preferences or requirements, 2. Clarify ambiguous instructions, 3. Get decisions on implementation choices, 4. Offer choices to the user about what direction to take. An 'Other' option that allows free-form input is automatically provided to the user, so do NOT include 'Other' or similar options in your options array. If you want to ask a question referring to work you did (e.g., a plan you wrote), you must write that work as a message to the user AND end your turn (give them a chance to read and respond) BEFORE using this tool.

Example:
{ "questions": [
  { "question": "Should the frobnosticator run on startup?", "options": ["Yes, run automatically", "No, only on demand"] },
  { "question": "Where should the thingamajig be displayed?", "options": ["In the sidebar", "In the top bar", "In a popover"] }
] }

