	if err != nil {
		t.Fatalf("glob stream sidecars: %v", err)
	}
	if len(streams) != 1 {
		t.Fatalf("expected exactly one stream sidecar, found %d: %v", len(streams), streams)
	}

	records := readGzip(t, streams[0])
