		var fromID, toID string
		if err := scan(&fromID, &toID); err != nil {
			return err
		}
		cache.UnmergedDataFlowEdges = append(cache.UnmergedDataFlowEdges, [2]string{fromID, toID})
		return nil
	}); err != nil {
