// searchStoreEnabled gates the READ path while the store rolls out: the
// artifact is always written beside the JSON entry, but it is only served when
// the operator opts in, so a rollout problem degrades to the measured JSON
// path rather than to a broken query.
func searchStoreEnabled(lookupEnv func(string) (string, bool)) bool {
	if lookupEnv == nil {
		lookupEnv = os.LookupEnv
	}
	value, ok := lookupEnv("ENTIRE_GRAPH_SEARCH_STORE")
	if !ok {
		return false
	}
	switch strings.TrimSpace(strings.ToLower(value)) {
	case "", "0", "false", "off", "no":
		return false
	}
	return true
}

