// searchStorePathForEntry names the store artifact beside a search snapshot
// cache entry: the entry's path with the .sqlite suffix replacing .json.gz.
func searchStorePathForEntry(entry cacheEntry) string {
	relative := strings.TrimSuffix(entry.relative, ".json.gz") + ".sqlite"
	return filepath.Join(entry.root, relative)
}

// writeSearchStoreSidecar builds the sqlite sidecar for an entry that was just
// written with entryDigest. It goes through the same confined directory walk
// every cache write uses, builds into a temporary, and renames into place. On
// ANY failure it removes both the temporary and any previous sidecar: the
// invariant readers rely on is that a sidecar present on disk was written by
// the same call that wrote the current entry (the digest check backstops the
// crash window between the two renames).
func writeSearchStoreSidecar(ctx context.Context, entry cacheEntry, entryDigest string, cache *cachedSearchSnapshot) error {
	if err := os.MkdirAll(entry.root, 0o700); err != nil {
		return err
	}
	root, err := os.OpenRoot(entry.root)
	if err != nil {
		return err
	}
	defer root.Close()
	directory, err := openCacheDirectory(root, filepath.Dir(entry.relative))
	if err != nil {
		return err
	}
	defer directory.Close()
	sidecarName := strings.TrimSuffix(filepath.Base(entry.relative), ".json.gz") + ".sqlite"
	discardPrevious := func() {
		_ = directory.Remove(sidecarName)
	}
	temporary, temporaryName, err := createRootTemp(directory, "store")
	if err != nil {
		discardPrevious()
		return err
	}
	if err := temporary.Close(); err != nil {
		_ = directory.Remove(temporaryName)
		discardPrevious()
		return err
	}
	temporaryPath := filepath.Join(entry.root, filepath.Dir(entry.relative), temporaryName)
	if err := buildSearchStore(ctx, temporaryPath, entryDigest, cache); err != nil {
		_ = directory.Remove(temporaryName)
		discardPrevious()
		return err
	}
	if err := directory.Rename(temporaryName, sidecarName); err != nil {
		_ = directory.Remove(temporaryName)
		discardPrevious()
		return err
	}
	return nil
}

