// normalizeSearchStoreCache clears representation-only differences that carry
// no information: nil vs empty maps/slices decode differently between the two
// containers, and slice order of the ID lists is unspecified set membership.
func normalizeSearchStoreCache(cache cachedSearchSnapshot) cachedSearchSnapshot {
	if len(cache.FileLines) == 0 {
		cache.FileLines = nil
	}
	if len(cache.SymbolByteRanges) == 0 {
		cache.SymbolByteRanges = nil
	}
	if len(cache.SymbolParameterNames) == 0 {
		cache.SymbolParameterNames = nil
	}
	if len(cache.SymbolSignatureTypes) == 0 {
		cache.SymbolSignatureTypes = nil
	}
	if len(cache.SymbolNameLines) == 0 {
		cache.SymbolNameLines = nil
	}
	cache.LocalSymbolIDs = slices.Sorted(slices.Values(cache.LocalSymbolIDs))
	cache.BodylessSymbolIDs = slices.Sorted(slices.Values(cache.BodylessSymbolIDs))
	cache.SymbolParameterNamesKnownIDs = slices.Sorted(slices.Values(cache.SymbolParameterNamesKnownIDs))
	if len(cache.LocalSymbolIDs) == 0 {
		cache.LocalSymbolIDs = nil
	}
	if len(cache.BodylessSymbolIDs) == 0 {
		cache.BodylessSymbolIDs = nil
	}
	if len(cache.SymbolParameterNamesKnownIDs) == 0 {
		cache.SymbolParameterNamesKnownIDs = nil
	}
	if len(cache.UnmergedDataFlowEdges) == 0 {
		cache.UnmergedDataFlowEdges = nil
	}
	return cache
}

